{
  "name": "@angular/compiler-cli",
  "version": "0.0.0-PLACEHOLDER",
  "description": "Angular - the compiler CLI for Node.js",
  "typings": "index.d.ts",
  "bin": {
    "ngc": "./bundles/src/bin/ngc.js",
    "ng-xi18n": "./bundles/src/bin/ng_xi18n.js"
  },
  "type": "module",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "default": "./bundles/index.js"
    },
    "./package.json": {
      "default": "./package.json"
    },
    "./linker": {
      "types": "./linker/index.d.ts",
      "default": "./bundles/linker/index.js"
    },
    "./linker/babel": {
      "types": "./linker/babel/index.d.ts",
      "default": "./bundles/linker/babel/index.js"
    },
    "./private/*": {
      "types": "./private/*.d.ts",
      "default": "./bundles/private/*.js"
    }
  },
  "dependencies": {
    "@babel/core": "8.0.7",
    "@jridgewell/sourcemap-codec": "^1.6.0",
    "reflect-metadata": "^0.2.0",
    "chokidar": "^5.0.0",
    "convert-source-map": "^1.5.1",
    "semver": "^7.0.0",
    "tslib": "^2.3.0",
    "yargs": "^18.0.0"
  },
  "devDependencies": {
    "typescript": "6.0.3",
    "@types/convert-source-map": "^2.0.0"
  },
  "peerDependencies": {
    "@angular/compiler": "0.0.0-PLACEHOLDER",
    "typescript": ">=6.0 <6.1"
  },
  "peerDependenciesMeta": {
    "typescript": {
      "optional": true
    }
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/angular/angular.git",
    "directory": "packages/compiler-cli"
  },
  "keywords": [
    "angular",
    "compiler"
  ],
  "license": "MIT",
  "engines": {
    "node": "^22.22.3 || ^24.15.0 || >=26.0.0"
  },
  "bugs": {
    "url": "https://github.com/angular/angular/issues"
  },
  "homepage": "https://github.com/angular/angular/tree/main/packages/compiler-cli",
  "ng-update": {
    "packageGroup": "NG_UPDATE_PACKAGE_GROUP"
  }
}
